INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'Geography', 'Unit 8', 'Molarum Grade 10 — Geography Unit 8: Geospatial Information and Data Processing', 'Source-grounded Molarum Grade 10 Geography questions for Unit 8: Geospatial Information and Data Processing.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('e109bb43-1e68-44cd-8961-138091af1191'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following statements about data is CORRECT according to the unit?', 'Data is used as an input for the computer system.', 'The unit states that data are unprocessed facts used as input to computer systems, whereas information is the processed output derived from data.', 0),('4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is NOT listed as a stage in the data lifecycle in the unit?', 'Data manufacturing', 'The unit lists collection, processing (QA/QC), analysis and dissemination as stages; ''data manufacturing'' is not mentioned.', 1),('d00a1013-995d-4197-8267-eadad2d52705'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'According to the unit, a GPS receiver must connect with how many satellites to calculate a precise location?', 'Four or more satellites', 'The text states a GPS receiver needs to connect with four or more satellites to calculate the precise location within a few meters.', 2),('35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'What is the primary purpose of a digitizer as described in the unit?', 'To change images on an analogue form or paper into a digital form on a computer.', 'The unit defines a digitizer as the tool that converts analogue paper images into digital, computer-readable formats.', 3),('6b4889f4-fc88-4d13-8f0c-82a3fb673b3f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is given in the unit as an example of directly collected geographic data?', 'Temperature readings at specific weather stations', 'The unit states directly collected data include measurements at the source such as temperature readings at weather stations, while satellite images and aerial photos are remotely sensed.', 4),('980f4c50-40b7-4835-8d90-b64e63d482dc'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following terms does the unit NOT list among the key terms in section 8.1?', 'Topography', 'The unit''s key term list includes Attribute, Continuous data and Temporal information but does not list ''Topography''.', 5),('b9154b44-6e9d-4b28-80dd-77dbf68fb07b'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Why does the unit say ''place'' or location is essential when collecting geographical data?', 'Because locations are the basis for mapping and allow linking information and measuring distances and areas.', 'The unit explains place is essential because locations form the basis for mapping, linking different information and measuring distances and areas.', 6),('faba4cc1-057b-42d5-89a8-f4760326e799'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'The unit describes ''time'' in geospatial data as:', 'An optional element because some surface features change slowly and time can often be omitted.', 'The text states time is optional since many surface features change very slowly and can be omitted for many applications.', 7),('77e1365e-49df-4d6a-87c6-80209973c59d'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is given in the unit as an example of a discrete object in geographic data?', 'Lake', 'The unit uses a lake as an example of a discrete object with well-defined boundaries, whereas elevation and temperature are continuous.', 8),('b981d23f-d97d-49f6-8867-a1c1ba0cea39'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following does the unit list as an example of continuous (field) data?', 'Elevation', 'The unit gives elevation as an example of continuous data that varies progressively across a surface.', 9),('b2e87ccb-bb9d-496c-8015-cbff20acb50e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'The unit states there are two fundamental ways of visualizing geographic data. Which of the following is NOT one of them?', 'Categorical clustering', 'The text names discrete objects and continuous data as the two fundamental visualization ways; ''categorical clustering'' is not listed.', 10),('e21908ec-5da3-4073-8f3c-870542c89c93'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is listed in the unit as a common general source for geographic data?', 'Hard copy maps (analogue maps)', 'The unit lists hard copy (analogue) maps among the most common general sources for geographic data; the other options are not listed.', 11),('d7f7c578-2413-481c-8a81-1b6f8c6050e2'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which product does the unit say a GPS receiver provides that is valuable for documenting information about a place?', 'Latitudinal and longitudinal coordinate values and elevation', 'The unit explains GPS receivers provide latitudinal and longitudinal coordinates and elevation values useful for documenting places.', 12),('5162eea8-921f-41ba-80fd-f57f5f2dd999'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'According to the unit, which statement about outputs of digitizers and scanners is TRUE?', 'Data generated by digitizers provides geo-referenced information, while images from scanners should be geo-referenced.', 'The text states digitizers yield geo-referenced data, whereas scanner images should be geo-referenced to relate internal coordinates to geographic coordinates.', 13),('b130ac39-ddba-4c8c-80cd-018ba54f4505'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which advantage of digital geographic data over hardcopy does the unit explicitly mention?', 'Digital data are easy to copy and transmit at very high speeds.', 'The unit lists that digital data are easy to copy and transmit quickly, and are easier to transform, process and analyze compared to hardcopy.', 14),('967e76ca-5bda-491f-8149-10dd2d91f5ae'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'A map is composed of geographic features represented in which basic forms, according to the unit?', 'Points, lines and/or areas (polygons)', 'The unit states maps model real-world features as points, lines and areas, each defined by location and attributes.', 15),('b3c5ce7d-93f8-4d28-81a2-678d523ade80'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'In the vector data model described in the unit, what is a ''node''?', 'A vertex that starts or ends an arc segment', 'The unit defines a node as a vertex that starts or ends an arc (line) segment in vector storage.', 16),('59e5a741-8a37-4b7d-8a06-61d7e6bef8b7'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'How does the unit say raster data represent area (polygonal) features?', 'By collections of contiguous cells', 'The text explains raster represents areas by collections of contiguous grid cells; points by single cells and lines by sequences of neighboring cells.', 17),('6d0fdd5a-1c14-489a-8718-fa458f771951'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which of the following is identified in the unit as a component of GIS?', 'Hardware', 'The unit lists hardware (computers and peripheral devices) as one of the GIS components.', 18),('2f643454-2fa8-45cd-8bae-f4087db53ccb'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'multiple_choice', 'Which historical advance does the unit credit with helping mapmakers locate precise positions on Earth?', 'Dividing the Earth into lines of longitude and latitude', 'The unit notes that advances in mathematics and astronomy and dividing Earth into longitude and latitude were notable for improving map accuracy.', 19),('826490a3-6eeb-4fe1-8c1b-112a98aa7e2f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'Time is always required when representing geographical data according to the unit.', 'False', 'The unit explicitly states time is optional because many surface features change slowly and time can often be omitted.', 20),('970a2275-43b6-454d-8ec1-bb789ae32356'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'Remotely sensed data are measured without direct contact with the phenomena or a need to visit locations of interest.', 'True', 'The unit defines remotely sensed data as measured from remote distances without direct contact or visiting the location of interest.', 21),('76551550-3dd5-4bb6-81fc-658b31adc364'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'The unit states that digital geographic data are easy to transform, process and analyze compared to hardcopy.', 'True', 'The text lists ease of transformation, processing and analysis as advantages of digital formats over hardcopy.', 22),('7ac53e8e-49b1-46ce-85db-54dcb68fa81d'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'true_false', 'In the vector data model a point feature is defined by one coordinate pair of X and Y.', 'True', 'The unit states that a point feature is defined by one coordinate pair (X and Y) in the vector model.', 23),('41a226d1-15ab-4e4f-837e-043cd714277e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Define geospatial data as described in the unit.', 'Data about objects, events or phenomena that include location information and often attribute and temporal information.', 'The unit defines geospatial data as data about phenomena that have location (coordinates) and attribute (and optionally temporal) information representing the Earth''s surface.', 24),('556f98b0-7cca-487f-85e1-8b78e4e7d378'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Name the two most important tools for geographic data collection highlighted in the unit.', 'Global Positioning System (GPS) and digitizers.', 'The unit explicitly names GPS and digitizers as the two most important tools or hardware for collecting geographic data.', 25),('a279fe05-25f6-4bf2-8719-c50e7cb5ccd4'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'List the four primary stages of the data lifecycle described in the unit.', 'Data collection, data processing (QA/QC), data analysis, and dissemination (including archiving).', 'The unit outlines a lifecycle that begins with collection, moves to processing (QA/QC), then analysis, and ends with dissemination and archiving for future use.', 26),('94fe1a56-b153-4f29-8a5c-43485688ffe0'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Give one example each of a directly collected source and a remotely sensed source as given in the unit.', 'Directly collected: temperature readings at a weather station; Remotely sensed: satellite images.', 'The unit gives temperature readings at specific stations as directly collected data and satellite images as remotely sensed data.', 27),('baecb721-a7f3-42bf-80d7-3b701482a876'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What are the three basic geographic feature types used to represent real-world features on maps?', 'Point, line and area (polygon).', 'The unit states that geographic features on maps are characterized as points, lines or areas (polygons), each defined by location and attributes.', 28),('3b7f2de4-9bca-4610-8376-fd2412fed2e0'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Briefly define a raster data model as described in the unit.', 'A grid-cell data structure dividing the area into cells (rows and columns) where attributes are assigned to cells.', 'The unit explains raster uses a tessellated grid of cells identified by row and column, with each cell classified by its most common attribute.', 29),('65bf1afa-a6e6-48c0-8eff-e843b9e45b3f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'Briefly define the vector data model as described in the unit.', 'A storage method using sequential points or vertices (X,Y pairs) to define points, lines (arcs) and closed coordinate pairs for polygons.', 'The unit describes vector storage as using sequential vertices (X and Y coordinates) to represent points, lines (arcs) and polygonal features.', 30),('cbceac12-c976-4c53-8390-f811a6e3278b'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What does georeferencing mean based on the unit''s explanation?', 'Relating the internal coordinate system of a map or image to a geographic coordinate system of the area being scanned.', 'The unit defines georeferencing as linking a map or aerial photo''s internal coordinates to a geographic coordinate system so location relates to real-world coordinates.', 31),('6ca02491-15bb-4fc3-88aa-6c7e4b1f3f09'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What is the minimum number of satellites a GPS receiver needs to connect with to calculate the precise location, as stated in the unit?', '4', 'The unit specifies a GPS receiver needs to connect with four or more satellites; the minimum number given is four.', 32),('fbedb200-8840-4a16-8959-911f09134360'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'According to the UNEP figure quoted in the unit, approximately how many tons of plastic were produced globally in 2020?', 'Over 400 million tons', 'The unit quotes UNEP''s estimate that total global plastic production in 2020 was over 400 million tons.', 33),('e959f634-241f-4cab-8674-9364a96c14d6'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What percentage of global plastic production in 2020 was produced in China according to the unit?', '28%', 'The unit states China accounted for 28% of global plastic production in 2020 according to UNEP.', 34),('867aaf7b-306a-4f36-89b6-f48f93ec812f'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'How many people were reported living in Africa as of 2020 in the unit?', '1.3 billion', 'The unit reports that 1.3 billion people were living in Africa in 2020, representing 16% of the world''s population.', 35),('7f59fca0-fecc-4273-8c00-80a8b51f72c1'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What percentage of global plastic volumes did Africa produce according to the unit?', '5%', 'The unit states Africa produced 5% of global plastic volumes in 2020.', 36),('ba7a781a-b777-4a72-8f89-55b3c2a9b0c4'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What was the plastic consumption in Africa in 2015 per person according to the unit (kg per person)?', '16 kg', 'The unit reports plastic consumption in Africa in 2015 was 16 kg per person.', 37),('8086cd50-4b22-432a-8a5f-529ef66fdf8e'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'What was the global average plastic consumption per person cited in the unit (kg per person)?', '45 kg', 'The unit gives the global average plastic consumption in 2015 as 45 kg per person.', 38),('aa5269c7-0f82-42ac-8086-d68a91c6d686'::uuid, '73ab3638-7005-4417-8cb3-55a51ef0e511'::uuid, 'fill_blank', 'According to the unit, what percentage of plastic is recycled in South Africa and approximately how many metric tons of discarded plastic end up in rivers?', '16% recycled; about 8 million metric tons discarded', 'The unit states in South Africa 16% of plastic is recycled and the remaining (about 8 million metric tons) is discarded and ends up in rivers.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('bb53aa2b-16ff-4a68-8f52-52b47ba3eb65'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Data is used as an input for the computer system.', TRUE, 0),('ed7549bf-4e98-4745-8070-c93df7467654'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Information is used as an input for the computer system.', FALSE, 1),('93ff62ab-b561-41c3-8e9b-0a23c5ae25d1'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Data is the processed output of a computer system.', FALSE, 2),('9ddb4d9a-cd14-4d57-85cb-a7ec72bcdbb3'::uuid, 'e109bb43-1e68-44cd-8961-138091af1191'::uuid, 'Information does not depend on data.', FALSE, 3),('0e7aefb7-4c90-4741-8590-9bbe4038cf6f'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data collection', FALSE, 0),('88c1418c-4850-4d65-853c-9109148e29bc'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data processing', FALSE, 1),('909142e5-1e61-4696-8c9f-16b06e969220'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data manufacturing', TRUE, 2),('f50f8b24-9529-481c-8090-dbe21ad93d89'::uuid, '4438a03d-8e19-4b7c-8353-86733dc29c76'::uuid, 'Data dissemination', FALSE, 3),('205f7b18-ea4c-4d18-8183-d872a8277600'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Two satellites', FALSE, 0),('3557d3d6-d97b-4ea3-8846-4e166bbbfef9'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Three satellites', FALSE, 1),('2fca5d9c-99b7-43b4-84cb-b3420a94a399'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Four or more satellites', TRUE, 2),('320ce40e-259d-43ec-89db-c4f45f99a10f'::uuid, 'd00a1013-995d-4197-8267-eadad2d52705'::uuid, 'Ten satellites', FALSE, 3),('e06dbadc-43c0-45e0-8c1c-a0890edb1976'::uuid, '35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, 'To change images on an analogue form or paper into a digital form on a computer.', TRUE, 0),('02852c70-c892-4152-8c26-f8e776bf0228'::uuid, '35bdcce0-bf39-40b4-806f-a672b6e9cf6e'::uuid, 'To measure temperature at